start_layer_i = {[1, 1, 1, 1, 1], ...
                 [2, 2, 3, 4, 4, 4, 6, 6, 6, 5], ...
                 [7, 7, 8, 10, 12, 14]};
end_layer_i = {[2 3 4 5 6], ...
               [7, 8, 7, 9, 10, 8, 11, 8, 14, 17], ...
               [15, 13, 16, 16, 20, 16]};

s = [start_layer_i{:}];
t = [end_layer_i{:}];
weights = [5 5 5 6 9 3 4 9 8 2 1 3 4 5 3 3 3 4 5 6 4]; % weights don't do anything here
G = digraph(s,t,weights) %[output:5e26fdc0]
figure %[output:496d0cb6]
plot(G) %[output:496d0cb6]
%%
% Filter
layer_valid_i = {};
layer_valid_i{1} = 1;
next_valid = end_layer_i{1};
for i = 2 : numel(start_layer_i)
    u_layer_start = unique(start_layer_i{i})';
    start_indeg = G.indegree(u_layer_start);
    start_filtered_i = u_layer_start(start_indeg ~= 0);
    
    u_layer_end = unique(end_layer_i{i - 1})';
    end_indeg = G.indegree(u_layer_end);
    end_filtered_i = u_layer_end(end_indeg ~= 0);

    layer_valid_i{i} = intersect(next_valid, intersect(start_filtered_i, end_filtered_i))';
    next_valid = unique(end_layer_i{i}(ismember(start_layer_i{i}, layer_valid_i{i})));
end
G2 = G.addnode(G.numnodes + 1);
G2 = G2.addedge(next_valid, (G.numnodes + 1) * ones([1, numel(next_valid)]), zeros([1, numel(next_valid)]));
G_valid = G2.subgraph([layer_valid_i{:}, next_valid, G.numnodes + 1]);
p = plot(G_valid); %[output:24a51daf]
%%
%G_valid.addnode();

%%
full(G_valid.adjacency) %[output:78ac4d2f]
a = G_valid.adjacency;
z = ~any(a, 2)  %[output:889dc1a6]
find(z(1 : (end - 1))) %[output:9f5132c1]
%%
for i = 1 : numel(start_layer_i)
    a = G_valid.adjacency;
    z = ~any(a, 2);
    bad_i = find(z(1 : (end - 1)));
    G_valid = G_valid.rmnode(bad_i);
end
figure; %[output:77581cea]
p = plot(G_valid); %[output:77581cea]
%%
[paths,edgepaths] = allpaths(G_valid,1,12) %[output:479a3874]
figure;
p = plot(G_valid);
%highlight(p,'Edges',edgepaths{7},'EdgeColor','r','LineWidth',1.5,'NodeColor','r','MarkerSize',6); hold on

